function buildIndex(customers) {
  return new Map(customers.map((c) => [c.id, c]));
}

function nameFor(index, id) {
  const customer = index.get(id);
  return customer ? customer.name : 'unknown';
}

function namesInOrder(orders, customers) {
  const byId = new Map(customers.map((c) => [c.id, c]));
  return orders.map((o) => byId.get(o.customerId).name);
}

function joinOrders(orders, customers) {
  const byId = new Map(customers.map((c) => [c.id, c]));
  return orders.map((o) => {
    const c = byId.get(o.customerId);
    return { id: o.id, customerName: c ? c.name : null };
  });
}

function ordersPerCustomer(orders) {
  const counts = new Map();
  for (const o of orders) {
    counts.set(o.customerId, (counts.get(o.customerId) || 0) + 1);
  }
  return [...counts.entries()];
}

function chunk(ids, size) {
  const out = [];
  for (let i = 0; i < ids.length; i += size) {
    out.push(ids.slice(i, i + size));
  }
  return out;
}
